parameters.jsCode:
// Consolida config_execucao.json + cobrancas.json + apelidos.json (binário -> JSON)
// e embute os 3 perfis de projeto (cópia de /profiles/*.json — seção 6 do spec.md).
// Perfis embutidos aqui (não buscados via HTTP), por decisão já confirmada.

// Leitura de binário: esta instância do n8n guarda binário no disco (filesystem-v2),
// então item.binary.data.data NÃO é o conteúdo, e sim o rótulo do modo de armazenamento.
// O único acesso liberado no Code Node é helpers.getBinaryDataBuffer, que lê pelo ÍNDICE
// do item no input DIRETO — daí localizarmos o item pelo id do binário. Cobre os 2 modos.
const helpers = this.helpers;
const entradasDoNode = $input.all();
async function bufferDe(item, prop) {
  prop = prop || 'data';
  const b = item && item.binary && item.binary[prop];
  if (!b) return null;
  if (!b.id) return Buffer.from(b.data, 'base64'); // modo embutido
  const i = entradasDoNode.findIndex((e) => e.binary && e.binary[prop] && e.binary[prop].id === b.id);
  if (i < 0) throw new Error('binario "' + (b.fileName || prop) + '" nao esta no input direto deste node — o Code Node so consegue le-lo por ai');
  return await helpers.getBinaryDataBuffer(i, prop);
}

async function parseBinaryJson(item) {
  if (!item || !item.binary || !item.binary.data) return {};
  const buffer = await bufferDe(item);
  return JSON.parse(buffer.toString('utf8'));
}

const config = await parseBinaryJson($('Ler config_execucao.json').first());
const cobrancas = await parseBinaryJson($('Ler cobrancas.json').first());
const apelidos = await parseBinaryJson($('Ler apelidos.json').first());

const perfis = {
  AREP: {
    projeto: 'AREP (S01 antigo)',
    prefixo_assunto_pedido: 'AREP | EMISSÃO DE NF',
    prefixo_assunto_entrega: 'AREP | NOTAS À PAGAR',
    texto_ref: 'SMTC',
    retranca: 'S01',
  },
  REUNION: {
    projeto: 'Reunion (S01)',
    prefixo_assunto_pedido: 'SMTC - S01 | REUNION | EMISSÃO DE NF',
    prefixo_assunto_entrega: 'SMTC - S01 | REUNION | NOTAS À PAGAR',
    texto_ref: 'SMTC - REUNION',
    retranca: 'REUNION_S01',
  },
  SOFT_PRE: {
    projeto: 'Soft Pré (S02)',
    prefixo_assunto_pedido: 'SMTC - S02 | SOFT PRE | EMISSÃO DE NF',
    prefixo_assunto_entrega: 'SMTC - S02 | SOFT PRE | NOTAS À PAGAR',
    texto_ref: 'SMTC - SOFT PRE',
    retranca: 'SOFT PRE_S02',
  },
};

// [gerado] ambiente fixado em tempo de geração — este arquivo é "homolog" e se comporta como tal,
// independente do que estiver no config_execucao.json da VM (evita, por exemplo,
// o arquivo de homolog mandar e-mail pra destinatário real por config divergente).
config.ambiente = 'homolog';

return [{ json: { config, cobrancas, apelidos, perfis, dominioEmpresa: 'novorealitybox.com' } }];

// Requer NODE_FUNCTION_ALLOW_EXTERNAL=exceljs,xlsx configurado na VM (spec.md 5 e 7.5).
// Duas bibliotecas de propósito, cada uma pelo que a outra não faz:
//   exceljs  -> Cost Report (.xlsx). É a única que expõe a COR de preenchimento da célula,
//               que é o que separa AREP de REUNION (spec 6).
//   SheetJS  -> Contratos (.xlsb). O exceljs não lê .xlsb — e pior, falha calado: abre o
//               arquivo e devolve zero abas, o que faria todo mundo virar "sem contrato".
// Os 5 arquivos chegam pelo "Merge — downloads + config", que tem a MESMA forma nos dois
// ambientes: input 0 = config (sem binário), 1 = Cost Report S01, 2 = Cost Report S02,
// 3/4/5 = Contratos AREP / Reunion / Soft Pré.
//
// Identificamos por POSIÇÃO, de propósito, e não por nome de node: quem baixa o Cost Report
// é o node do Box em produção e o do Drive em homolog, e o gerador remove o do ambiente que
// não é usado. Citar o nome no texto quebrava o arquivo de homolog com "Referenced node
// doesn't exist" — e quebrava só lá, o que é justamente o tipo de divergência que a fonte
// única existe pra evitar.
//
// A leitura em si usa helpers.getBinaryDataBuffer porque esta instância guarda binário no
// disco (filesystem-v2): ali binary.data.data é o rótulo do modo, não o conteúdo.
const helpers = this.helpers;
const entradasDoNode = $input.all();
const posicoesComBinario = [];
entradasDoNode.forEach((it, i) => { if (it.binary && it.binary.data) posicoesComBinario.push(i); });
if (posicoesComBinario.length !== 5) {
  throw new Error(
    'esperava 5 arquivos no input (2 Cost Reports + 3 planilhas de Contratos), vieram ' +
    posicoesComBinario.length + '. Confira as ligações do "Merge — downloads + config".'
  );
}
async function bufferNaPosicao(pos) {
  const i = posicoesComBinario[pos];
  const b = entradasDoNode[i].binary.data;
  if (!b.id) return Buffer.from(b.data, 'base64'); // modo embutido
  return await helpers.getBinaryDataBuffer(i, 'data');
}

const ExcelJS = require('exceljs');
const XLSX = require('xlsx');

function normalizar(texto) {
  if (!texto) return '';
  return String(texto).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}

// .text estoura com "Cannot read properties of null (reading 'toString')" quando a célula
// não tem valor — acontece de verdade nesta planilha, em células mescladas (ValueType 1).
// Esta versão do exceljs não protege esse caso.
function textoDaCelula(row, col) {
  try {
    const c = row.getCell(col);
    if (!c || c.value === null || c.value === undefined) return '';
    return c.text;
  } catch (e) {
    return '';
  }
}

// Mantém a semântica do original (Number(cell.value) || 0), só que sem estourar em célula
// vazia/mesclada e resolvendo célula de fórmula pelo resultado calculado.
function numeroDaCelula(row, col) {
  try {
    const c = row.getCell(col);
    const v = c && c.value;
    if (v && typeof v === 'object' && 'result' in v) return Number(v.result) || 0;
    return Number(v) || 0;
  } catch (e) {
    return 0;
  }
}

// getWorksheet() do exceljs é sensível a maiúsculas, e a aba real chama-se "NOTAS".
// O código antigo caía num fallback silencioso pro worksheets[0] e lia a aba errada
// ("DETALHADO MÃE"), sem nenhum sinal de erro.
function abaChamada(wb, nome) {
  const alvo = String(nome).trim().toUpperCase();
  return wb.worksheets.find((w) => String(w.name).trim().toUpperCase() === alvo) || null;
}

// Identificacao de projeto no S01 pela COR DE PREENCHIMENTO da linha (spec secoes 5 e 6):
// Reunion = roxo/cinza-arroxeado; AREP = sem preenchimento.
//
// DOIS bugs corrigidos aqui, ambos confirmados contra a planilha real:
//
// 1. A versao antiga so olhava fill.fgColor.argb. Esta planilha usa COR DE TEMA
//    (fgColor.theme + tint), onde argb e undefined — entao a funcao devolvia false pra
//    TODAS as 3.537 linhas e todo mundo virava AREP, inclusive linhas com "REUNION" na
//    propria descricao.
// 2. A cor era lida da coluna L, que e a de STATUS BOX e tem cor propria por status. Em
//    263 linhas o L e roxo enquanto a linha nao tem preenchimento nenhum — ler o L
//    classificaria essas 263 linhas AREP como Reunion. A leitura passou pra coluna H
//    (Fornecedor), que e coluna de dados.
//
// O roxo do Reunion neste arquivo e o tema 7 = accent4 = #8064A2 (conferido em
// xl/theme/theme1.xml). Aceitamos tambem o mesmo tom escrito como ARGB direto, caso a
// planilha passe a gravar a cor sem usar o tema.
const TEMA_REUNION = 7;
const ARGB_REUNION = '8064A2';
const COLUNA_DA_COR = 'H'; // coluna de dados — NUNCA a L (cor de status)

function corDePreenchimento(cell) {
  const fill = cell && cell.fill;
  if (!fill || fill.type !== 'pattern' || fill.pattern !== 'solid') return null;
  const fg = fill.fgColor || {};
  if (fg.argb) return { tipo: 'argb', valor: String(fg.argb).toUpperCase() };
  if (fg.theme !== undefined) return { tipo: 'theme', valor: fg.theme };
  return { tipo: 'desconhecido', valor: null };
}

function projetoPelaCorDaLinha(row) {
  const cor = corDePreenchimento(row.getCell(COLUNA_DA_COR));
  if (!cor) return 'AREP'; // sem preenchimento = AREP (spec secao 5)
  if (cor.tipo === 'theme') return cor.valor === TEMA_REUNION ? 'REUNION' : 'AREP';
  if (cor.tipo === 'argb') return cor.valor.slice(-6) === ARGB_REUNION ? 'REUNION' : 'AREP';
  return 'AREP';
}

async function lerAbaNotas(posicao, projetoFixo) {
  const buffer = await bufferNaPosicao(posicao);
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.load(buffer);
  const ws = abaChamada(wb, 'NOTAS');
  if (!ws) {
    throw new Error('aba "NOTAS" nao encontrada no Cost Report. Abas do arquivo: ' + wb.worksheets.map((w) => w.name).join(', '));
  }
  const linhas = [];
  ws.eachRow({ includeEmpty: false }, (row, rowNumber) => {
    if (rowNumber === 1) return; // cabeçalho
    const projetoId = projetoFixo || projetoPelaCorDaLinha(row);
    linhas.push({
      linha: rowNumber,
      projetoId,
      colunaB: textoDaCelula(row, 'B'),
      colunaC: textoDaCelula(row, 'C'),
      colunaG: textoDaCelula(row, 'G'),
      colunaH: textoDaCelula(row, 'H'),
      colunaJ: textoDaCelula(row, 'J'),
      colunaK: numeroDaCelula(row, 'K'),
      colunaL: textoDaCelula(row, 'L'),
      colunaN: textoDaCelula(row, 'N'),
      colunaR: textoDaCelula(row, 'R'),
    });
  });
  return linhas;
}

// Colunas localizadas pelo NOME do cabeçalho, não por letra fixa: as abas têm layouts
// diferentes (na de equipe a empresa fica em J; na de prestação de serviço, em F) e o
// cabeçalho está na linha 3, não na 1. Mapeamento por letra fixa lia as colunas erradas.
async function lerPlanilhaContratos(posicao) {
  const buffer = await bufferNaPosicao(posicao);
  const wb = XLSX.read(buffer, { type: 'buffer' });
  const linhas = [];

  // Só a aba "EQUIPE E E FORNECEDORES" (spec 3.1). O arquivo é da diretoria de Contratos e
  // a automação só lê — não cabe a ela decidir excluir aba. Restringindo à aba certa, as
  // demais (inclusive CANCELADOS_DISTRATOS) simplesmente nunca entram na leitura.
  const ABA_CONTRATOS = 'equipe e e fornecedores';
  const abasAlvo = wb.SheetNames.filter((s) => normalizar(s) === ABA_CONTRATOS);
  if (abasAlvo.length === 0) {
    throw new Error('aba "EQUIPE E E FORNECEDORES" nao encontrada na planilha de contratos. Abas: ' + wb.SheetNames.join(', '));
  }

  for (const nomeAba of abasAlvo) {
    const grade = XLSX.utils.sheet_to_json(wb.Sheets[nomeAba], { header: 'A', raw: false, defval: '' });

    let iCab = -1;
    for (let i = 0; i < Math.min(grade.length, 10); i++) {
      if (Object.values(grade[i]).some((v) => normalizar(v) === 'status')) { iCab = i; break; }
    }
    if (iCab < 0) continue;

    const col = {};
    for (const [letra, valor] of Object.entries(grade[iCab])) {
      const h = normalizar(valor);
      if (h === 'status') col.status = letra;
      else if (h === 'nome') col.nome = letra;
      else if (h.includes('informacoes da empresa')) col.empresa = letra;
    }
    if (!col.status) continue;

    for (const linha of grade.slice(iCab + 1)) {
      const razaoSocial = col.empresa ? String(linha[col.empresa] || '').trim() : '';
      const nomeColaborador = col.nome ? String(linha[col.nome] || '').trim() : '';
      if (!razaoSocial && !nomeColaborador) continue; // linha vazia ou separador
      linhas.push({ razaoSocial, nomeColaborador, status: String(linha[col.status] || '').trim() });
    }
  }

  if (linhas.length === 0) {
    throw new Error('planilha de contratos veio sem nenhuma linha legivel — confira o formato do arquivo');
  }
  return linhas;
}

const linhasS01 = await lerAbaNotas(0, null); // Cost Report S01 — a cor decide AREP/REUNION
const linhasS02 = await lerAbaNotas(1, 'SOFT_PRE'); // Cost Report S02

const contratos = {
  AREP: await lerPlanilhaContratos(2),
  REUNION: await lerPlanilhaContratos(3),
  SOFT_PRE: await lerPlanilhaContratos(4),
};

const cfg = $('Carregar config + perfis').first().json;

const todasAsLinhas = [...linhasS01, ...linhasS02];

// Os contratos NÃO vão em cada item, de propósito. O array do AREP tem ~60 KB; copiado
// nas ~3,9 mil linhas dá ~217 MB, que o n8n serializa a CADA salto de node — foi o que
// travou a VM (e2-small, 2 GB) na primeira execução em que o parse funcionou de verdade.
// Vai só no primeiro item, no campo contratosPorProjeto; a checagem de contrato lê de lá.
return todasAsLinhas.map((nota, indice) => ({
  json: {
    nota,
    ...(indice === 0 ? { contratosPorProjeto: contratos } : {}),
    config: cfg.config,
    cobrancas: cfg.cobrancas,
    apelidos: cfg.apelidos,
    perfil: cfg.perfis[nota.projetoId],
    dominioEmpresa: cfg.dominioEmpresa,
  },
}));

// Filtra só as linhas relevantes pra esta execução: candidatas a NOVO PEDIDO
// (Status Box = 'PROGRAMAR ATÉ [data]' ou variante de 'SOLICITAR') ou
// candidatas a MONITORAMENTO/COBRANÇA (Status Box = 'SOLICITADA MI').
// Linhas em qualquer outro estado (RECEBIDA MI, ENTREGUE, etc.) são ignoradas
// nesta fase — seção 3.1/3.1.1 do spec.md.

function ehVarianteSolicitar(statusBox) {
  return /^SOLICITAR/i.test((statusBox || '').trim());
}

// Escala de urgencia dentro de SOLICITAR (secao 3.1.4): 0 = mais urgente, 5 = menos.
// Literal ao spec: SO o sufixo "URG" e escala 0; qualquer outro sufixo cai na escala 1.
// Variantes reais hoje na planilha: "SOLICITAR" (32x) e "SOLICITAR / AGUARDAR DOCS" (1x).
// Nota: "SOLICITADA INFRA/BASE/MI" nao entram aqui — comecam com SOLICITADA, nao
// SOLICITAR, e nao casam com este filtro (so "SOLICITADA MI" tem tratamento proprio, no
// ramo de monitoramento).
const ESCALA_URGENTE = 0;
const ESCALA_PADRAO = 1;
const ESCALA_AGUARDAR_DOCS = 5;

function escalaDeUrgencia(statusBox) {
  const s = String(statusBox || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/\s+/g, ' ').trim();
  if (/AGUARDAR DOCS/.test(s)) return ESCALA_AGUARDAR_DOCS;
  // Variacoes de digitacao do mesmo token de urgencia contam todas como escala 0:
  // URG, URGENTE, URGENCIA (e URGÊNCIA — o acento ja caiu na normalizacao acima).
  // Continua sendo casamento de TOKEN dentro do texto, nao uma regra de escala nova.
  if (/\bURG(?:ENTE|ENCIA)?\b/.test(s)) return ESCALA_URGENTE;
  return ESCALA_PADRAO;
}

function extrairDataProgramarAte(statusBox, anoReferencia) {
  const m = /PROGRAMAR AT[ÉE]\s+(\d{1,2})[\/.](\d{1,2})(?:[\/.](\d{2,4}))?/i.exec(statusBox || '');
  if (!m) return null;
  const dia = parseInt(m[1], 10);
  const mes = parseInt(m[2], 10) - 1;
  const ano = m[3] ? (m[3].length === 2 ? 2000 + parseInt(m[3], 10) : parseInt(m[3], 10)) : anoReferencia;
  return new Date(ano, mes, dia);
}

const hoje = new Date();
const saida = [];

for (const item of $input.all()) {
  const { nota } = item.json;
  const dataProgramarAte = extrairDataProgramarAte(nota.colunaL, hoje.getFullYear());

  if (dataProgramarAte) {
    saida.push({ json: { ...item.json, fluxo: 'novo_pedido', gatilho: 'PROGRAMAR_ATE', dataProgramarAte: dataProgramarAte.toISOString() } });
  } else if (ehVarianteSolicitar(nota.colunaL)) {
    const escala = escalaDeUrgencia(nota.colunaL);
    saida.push({ json: {
      ...item.json,
      fluxo: 'novo_pedido',
      gatilho: 'SOLICITAR',
      escalaUrgencia: escala,
      // escala 5 = "SOLICITAR / AGUARDAR DOCS": e-mail SEMPRE rascunho, mesmo em
      // automatico + producao (unica excecao do sistema — secao 3.1.4). O flag viaja com
      // o item pra que a decisao de envio nao precise reinterpretar o texto do Status Box,
      // e a excecao nao possa vazar pra outra variante por engano.
      forcarRascunho: escala === ESCALA_AGUARDAR_DOCS,
    } });
  } else if (normalizarSimples(nota.colunaL) === 'solicitada mi') {
    saida.push({ json: { ...item.json, fluxo: 'monitoramento' } });
  }
  // demais status: ignorados nesta fase.
}

function normalizarSimples(t) { return (t || '').toLowerCase().trim(); }

return saida;

// 'Modo assistido' (secao 7.4): limite_linhas_execucao corta o numero de linhas
// processadas nesta execucao. null/0 = sem limite.
//
// ORDEM DE PRIORIDADE dentro do limite (confirmada por Claudio):
//   1o  SOLICITAR (e variantes) — pedido imediato, e o que a Michelle esta esperando sair
//   2o  PROGRAMAR ATE          — tem data marcada, aguenta a proxima execucao
//   3o  Monitoramento          — so se sobrar vaga; cobranca pode esperar
// Vale igual em homolog e producao.
//
// O corte era pela ordem da planilha: com limite baixo, uma leva de linhas de
// monitoramento no topo consumia as vagas e nenhum pedido saia.
//
// A ordenacao roda mesmo SEM limite. Nao muda o que e processado, so a ordem — e
// mantem o comportamento previsivel entre uma execucao limitada e uma sem limite.

function prioridade(d) {
  if (d.fluxo === 'novo_pedido' && d.gatilho === 'SOLICITAR') return 0;
  if (d.fluxo === 'novo_pedido' && d.gatilho === 'PROGRAMAR_ATE') return 1;
  if (d.fluxo === 'monitoramento') return 2;
  return 3; // nao previsto: fica por ultimo em vez de furar a fila
}

// Desempate DENTRO da categoria SOLICITAR: escala 0 -> 1 -> 5 (secao 3.1.4). Nas outras
// categorias nao existe escala, entao todas empatam em 0 e a ordem da planilha decide.
function subPrioridade(d) {
  if (d.fluxo === 'novo_pedido' && d.gatilho === 'SOLICITAR') {
    return typeof d.escalaUrgencia === 'number' ? d.escalaUrgencia : 1;
  }
  return 0;
}

const config = $('Carregar config + perfis').first().json.config;
const limite = config && config.limite_linhas_execucao;

// sort do JS e estavel: dentro da mesma prioridade, a ordem da planilha e preservada
const itens = $input.all().slice().sort((a, b) =>
  (prioridade(a.json) - prioridade(b.json)) || (subPrioridade(a.json) - subPrioridade(b.json)));

if (!limite || limite <= 0) return itens;
return itens.slice(0, limite);

// Checagem de contrato — passo 1 (spec 3.1): a coluna N do Cost Report.
// Aqui o critério é "CONTÉM assinado" (o spec dá "OK - Assinado" como exemplo válido) —
// diferente do critério da planilha de Contratos, que é o literal exato. São regras
// distintas de propósito; não dá pra unificar as duas.
//
// Se a coluna N já resolve, nem planilha nem Gmail precisam ser consultados. Se não
// resolve, as DUAS checagens rodam em paralelo (spec 3.1), sem prioridade entre si.
// Itens de fluxo='monitoramento' não passam por checagem de contrato nenhuma.

function normalizar(texto) {
  if (!texto) return '';
  return String(texto).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}

return $input.all().map((item) => {
  const { nota, fluxo } = item.json;
  const chaveLinha = nota ? (nota.projetoId + '|' + nota.linha) : null;

  if (fluxo !== 'novo_pedido') {
    return { json: { ...item.json, chaveLinha, contratoResolvido: true } };
  }

  const liberado = normalizar(nota.colunaN).includes('assinado');
  return { json: {
    ...item.json,
    chaveLinha,
    liberado,
    motivoLiberacao: liberado ? 'coluna_n' : undefined,
    // coluna N já está preenchida: não há o que reescrever nela
    contratoResolvido: liberado,
  } };
});

// Checagem B das duas paralelas (spec 3.1): ficha cadastral respondida na thread
// marcada CONTRATAÇÃO. Sinal válido = mensagem de remetente FORA do domínio da empresa
// com pelo menos 1 anexo (spec 3.1) — o anexo do pedido original não conta.
//
// As mensagens são reagrupadas POR LINHA via pairedItem. O node do Gmail roda uma busca
// por linha e devolve tudo achatado num fluxo só; sem reagrupar, o anexo de um colaborador
// validaria a linha de outro, e só a primeira linha sobreviveria.

function normalizar(texto) {
  if (!texto) return '';
  return String(texto).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}

function indiceDeOrigem(item) {
  const p = item.pairedItem;
  if (p === undefined || p === null) return null;
  if (typeof p === 'number') return p;
  if (Array.isArray(p)) return p.length && p[0] ? p[0].item : null;
  return p.item === undefined ? null : p.item;
}

function validarFichaCadastral(mensagens, dominioEmpresa) {
  const dominioNorm = normalizar(dominioEmpresa);
  return (mensagens || []).some((msg) => {
    const from = (msg.from || (msg.headers && msg.headers.from) || '');
    const dominioRemetente = normalizar((from.split('@')[1] || '').replace('>', ''));
    const externo = dominioRemetente !== '' && dominioRemetente !== dominioNorm;
    const temAnexo = !!(msg.hasAttachment || (msg.payload && msg.payload.parts && msg.payload.parts.some((p) => p.filename)));
    return externo && temAnexo;
  });
}

const origem = $('Preparar checagem paralela de contrato').all().map((i) => i.json);

const mensagensPorLinha = new Map();
for (const item of $input.all()) {
  const i = indiceDeOrigem(item);
  if (i === null || !origem[i]) continue;
  const chave = origem[i].chaveLinha;
  if (!mensagensPorLinha.has(chave)) mensagensPorLinha.set(chave, []);
  mensagensPorLinha.get(chave).push(item.json);
}

// Devolve UMA linha por linha de origem, mesmo sem mensagem nenhuma — assim o
// consolidador sempre recebe o par completo das duas checagens.
return origem.map((linha) => {
  const mensagens = mensagensPorLinha.get(linha.chaveLinha) || [];
  const confirmado = validarFichaCadastral(mensagens, linha.dominioEmpresa || 'novorealitybox.com');
  return { json: {
    ...linha,
    fonteChecagem: 'ficha_cadastral',
    confirmado,
    atualizarColunaNPara: confirmado ? 'OK - ASSINADO' : undefined,
  } };
});

// Interpreta a resposta da IA — nunca lanca excecao, falha vira situacaoNaoMapeada
// (regra geral de seguranca, secao 3.2 item 6: nunca adivinhar, sempre alertar).
//
// DOIS consertos, ambos vistos na execucao 75:
//
// 1. A IA devolve o JSON dentro de um bloco cercado (```json ... ```), que e comportamento
//    normal do modelo. JSON.parse direto no texto falhava e a linha virava "situacao nao
//    mapeada" mesmo com a resposta PERFEITA.
// 2. O node HTTP SUBSTITUI o json do item pela resposta da API: nota, perfil, config,
//    apelidos, liberado, gatilho — tudo se perdia aqui. O alerta no Telegram saiu
//    literalmente como "undefined", e a montagem do e-mail tambem ficaria sem os dados da
//    linha. O contexto e reanexado casando pelo pairedItem.

function indiceDeOrigem(item) {
  const p = item.pairedItem;
  if (p === undefined || p === null) return null;
  if (typeof p === 'number') return p;
  if (Array.isArray(p)) return p.length && p[0] ? p[0].item : null;
  return p.item === undefined ? null : p.item;
}

function extrairJson(texto) {
  const t = String(texto || '').trim();
  const cercado = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const bruto = cercado ? cercado[1] : t;
  const inicio = bruto.indexOf('{');
  const fim = bruto.lastIndexOf('}');
  return inicio >= 0 && fim > inicio ? bruto.slice(inicio, fim + 1) : bruto;
}

function parseRespostaIA(textoResposta) {
  try {
    const obj = JSON.parse(extrairJson(textoResposta));
    if (!obj || !obj.tipoLinha) return { situacaoNaoMapeada: 'Resposta da IA sem tipoLinha: ' + String(textoResposta).slice(0, 300) };
    return obj;
  } catch (e) {
    return { situacaoNaoMapeada: 'Resposta da IA nao e JSON valido: ' + String(textoResposta).slice(0, 300) };
  }
}

// Cargo sem numeracao (spec 3.1, item 6). A regra tambem foi pro prompt, mas nao dependemos
// do modelo obedecer: aqui e deterministico. Tira numeracao no FIM do cargo, com ou sem
// separador ("ASS. DE CONTROLLER 1", "CONTRARREGRA - 2", "CAMERA nº 3" -> sem o numero).
// Numero no meio do texto e preservado, que nao e numeracao de posto.
function cargoSemNumeracao(cargo) {
  if (!cargo || cargo === 'FALTA INFORMACAO' || cargo === 'FALTA INFORMAÇÃO') return cargo;
  // O separador e OBRIGATORIO ([\s\-–—]+): sem isso, "MOTORISTA 4X4" perdia o 4 final.
  // So conta como numeracao o numero destacado do resto do texto.
  const limpo = String(cargo).replace(/[\s\-–—]+(?:n[º°o]?\.?\s*)?\d+\s*$/i, '').trim();
  return limpo || cargo; // se sobrar vazio, mantem o original em vez de apagar o campo
}

const origem = $('Preparar chamada da IA (coluna J)').all().map((i) => i.json);

return $input.all().map((item, i) => {
  const idx = indiceDeOrigem(item);
  const contexto = (idx !== null && origem[idx]) ? origem[idx] : (origem[i] || {});
  const textoResposta = item.json.content && item.json.content[0] ? item.json.content[0].text : '';
  const resultado = parseRespostaIA(textoResposta);
  if (resultado.cargo) resultado.cargo = cargoSemNumeracao(resultado.cargo);
  return { json: { ...contexto, ...resultado } };
});

// Monta o texto do alerta AQUI, e nao na expressao do node do Telegram.
// Na execucao 75 a expressao era '... ' + $json.nota.projetoId + ' ...' e, com nota
// ausente, o n8n resolveu a expressao inteira como "undefined" — a mensagem chegou, mas
// sem nenhuma informacao. Montando no Code, um campo faltando vira "?" e o resto do alerta
// continua legivel.
return $input.all().map((item) => {
  const d = item.json;
  const nota = d.nota || {};
  const texto = [
    '⚠️ Situação não mapeada (Fase 1)',
    '',
    'Projeto: ' + (nota.projetoId || '?'),
    'Linha: ' + (nota.linha || '?'),
    'Fornecedor/Descrição: ' + (nota.colunaH || nota.colunaJ || '?'),
    '',
    String(d.situacaoNaoMapeada || 'sem detalhe'),
  ].join('\n');
  return { json: { ...d, acao: 'alerta_situacao_nao_mapeada', textoAlerta: texto } };
});

