function envolverCorpo(partes) {
  return '<div style="font-family:' + FONTE_EMAIL + ';">\n' + partes.filter(Boolean).join('\n') + '\n</div>';
}

// "...enviada até o dia DD/MM" -> cor só na data. "vencimento em DD/MM/AAAA." -> negrito no
// trecho inteiro, com highlight só nos números da data.
function paragrafoAbertura(dataEnvio, dataVencimento, doisDocumentos) {
  const verbo = doisDocumentos
    ? 'Seguem as instruções para a emissão do RECIBO e da NOTA FISCAL que deverão ser enviadas '
    : 'Seguem as instruções para a emissão da sua nota fiscal que deverá ser enviada ';
