  // "vencimento em DD/MM/AAAA." INTEIRO com o highlight; o ponto final fica DENTRO do
  // highlight e FORA do negrito (3.5).
  const vencimento = '<span style="background-color:' + FUNDO_VENCIMENTO + ';">' +
    '<b>vencimento em ' + formatarDataBR(dataVencimento) + '</b>.</span>';
  return '<p>' + verbo + ateODia + ' com ' + vencimento + '</p>';
}

function blocoEmitir(numero, textoDocumento, valor) {
  const valorFmt = valor.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return '<p><span style="background-color:' + FUNDO_BLOCO_EMITIR + ';">' + numero +
    '- Emitir ' + textoDocumento + ' no valor de <b>R$ ' + valorFmt + '</b> com os dados abaixo no corpo da nota:</span></p>';
}

function blocoDadosBancarios() {
  // Sem <p> vazio entre "Período de" e "Dados bancários": a 3.5 (referência Paulo Bento)
  // pede parágrafos sequenciais, com o espaçamento vindo só da margem padrão do <p>.
  return '<p><b>Dados bancários:</b></p>\n<p><b>Chave pix:</b></p>\n' +
    '<p>---------------------------------------------------------------------</p>';
}

function normalizar(t) { return t ? String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim() : ''; }
function formatarDataBR(d) { return String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0') + '/' + d.getFullYear(); }
// Data do "ate o dia" no CORPO: DD/MM, sem ano — formato diferente do vencimento
// (DD/MM/AAAA), de proposito (3.5, confirmado com e-mail padrao de producao).
// Nao confundir com formatarDataCurta, que e DD.MM com PONTO e vale pro ASSUNTO.
function formatarDataDiaMes(d) { return String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0'); }
function formatarDataCurta(d) { return String(d.getDate()).padStart(2,'0') + '.' + String(d.getMonth()+1).padStart(2,'0'); }
// O apelido de projeto (apelidos.json) e so o identificador: "AREP", "SMTC - S01 | REUNION".
// Ja o prefixo_assunto_pedido do perfil vem com "| EMISSAO DE NF" embutido (spec secao 6).
// Como o assunto concatena a palavra do documento logo depois, usar o prefixo cru no
// fallback duplicava o trecho ("... | EMISSAO DE NF | EMISSAO DE NF | REF. ..."). Nao
// aparecia em execucao porque hoje o apelidos.json cobre os 3 projetos e o fallback nunca
// roda — mas passaria a aparecer se um projeto sumisse do arquivo.
function apelidoDoPerfil(perfil) {
  return String((perfil && perfil.prefixo_assunto_pedido) || '')
    .replace(/\s*\|\s*EMISS[ÃA]O DE .*$/i, '')
    .trim();
}
function ehModoAutomatico(config) { return config && config.modo === 'automatico'; }
function decidirAcaoEnvio(gatilho, modoAutomatico, forcarRascunho) {
  // "SOLICITAR / AGUARDAR DOCS" (escala 5) SEMPRE fica em rascunho, mesmo em
  // MODO_EXECUCAO=automatico e ambiente producao — unica excecao do sistema (secao 3.1.4).
  // O flag vem pronto do node de filtro: nao reinterpretamos o Status Box aqui, pra que a
  // excecao nao possa vazar pra outras variantes.
  if (forcarRascunho) return { acaoGmail: 'criar_rascunho', atualizarColunaL: false };
  if (!modoAutomatico) return { acaoGmail: 'criar_rascunho', atualizarColunaL: false };
  if (gatilho === 'SOLICITAR') return { acaoGmail: 'enviar_direto', atualizarColunaL: true, novoValorColunaL: 'SOLICITADA MI' };
  return { acaoGmail: 'agendar_envio', atualizarColunaL: true, novoValorColunaL: 'SOLICITADA MI' };
}
function agruparLinhasFornecedor(itens) {
  const grupos = new Map();
  for (const item of itens) {
    const chave = [item.nota.projetoId, normalizar(item.nota.colunaH), item.nota.colunaG].join('|');
    if (!grupos.has(chave)) grupos.set(chave, []);
    grupos.get(chave).push(item);
  }
  return Array.from(grupos.values());
}
function ordenarBlocosGrupo(grupo) {
  const recibos = grupo.filter((i) => i.documentoLinha === 'RECIBO');
  const notas = grupo.filter((i) => i.documentoLinha === 'NOTA_FISCAL');
  const semClassificacao = grupo.filter((i) => i.documentoLinha !== 'RECIBO' && i.documentoLinha !== 'NOTA_FISCAL');
  return { blocosOrdenados: [...recibos, ...notas], semClassificacao };
}
function montarBlocoRecibo(numero, item, textoRef) {
  return [
    blocoEmitir(numero, 'RECIBO', item.nota.colunaK),
    '<p>Ref. "' + textoRef + '"</p>',
    '<p><b>Fornecedor:</b> ' + item.nota.colunaH + '</p>',
    '<p><b>Período de</b> ' + (item.periodo || '') + ' - ' + item.descricaoServicoOuLocacao + '</p>',
    blocoDadosBancarios(),
  ].join('\n');
}
function montarBlocoNotaFiscal(numero, item, textoRef) {
  return [
    blocoEmitir(numero, 'NOTA FISCAL', item.nota.colunaK),
    '<p>Ref. "' + textoRef + '"</p>',
    '<p><b>Fornecedor:</b> ' + item.nota.colunaH + '</p>',
    '<p><b>Serviço Prestado:</b> ' + item.descricaoServicoOuLocacao + '</p>',
    '<p><b>Período de</b> ' + (item.periodo || '') + '</p>',
    blocoDadosBancarios(),
  ].join('\n');
}
function montarCorpoEmailFornecedor({ blocosOrdenados, temNotaFiscal, dataEnvio, dataVencimento, textoRef }) {
  const blocos = blocosOrdenados.map((item, idx) => item.documentoLinha === 'RECIBO'
    ? montarBlocoRecibo(idx + 1, item, textoRef)
    : montarBlocoNotaFiscal(idx + 1, item, textoRef));
  return envolverCorpo([
    '<p>Olá! Tudo bem? 😊</p>',
    paragrafoAbertura(dataEnvio, dataVencimento, temNotaFiscal),
    TOMADOR_HTML,
    blocos.join('\n'),
    IMPORTANTE_HTML,
    AVISO_HTML,
  ]);
}
function montarAssuntoFornecedor({ apelidoAtual, temNotaFiscal, parcela, dataEnvio, fornecedor }) {
  const mes = MESES_ABREV_PT[dataEnvio.getMonth()];
  const palavraDocumento = temNotaFiscal ? 'EMISSÃO DE FATURA' : 'EMISSÃO DE RECIBO';
  const ref = temNotaFiscal ? ('REF. LOCAÇÃO E SERVIÇOS - ' + mes) : ('REF. LOCAÇÃO - ' + mes + (parcela ? (' - ' + parcela) : ''));
  return apelidoAtual + ' | ' + palavraDocumento + ' | ' + ref + ' | (ENVIAR ATÉ ' + formatarDataCurta(dataEnvio) + ') | ' + fornecedor;
}

const hoje = new Date();
const itens = $input.all().map((i) => i.json);
const grupos = agruparLinhasFornecedor(itens);
const saida = [];

for (const grupo of grupos) {
  const { blocosOrdenados, semClassificacao } = ordenarBlocosGrupo(grupo);

  if (semClassificacao.length > 0) {
    saida.push({ json: { ...semClassificacao[0], acao: 'alerta_situacao_nao_mapeada', situacaoNaoMapeada: 'Não foi possível classificar RECIBO/NOTA_FISCAL para ' + semClassificacao.length + ' linha(s) do fornecedor ' + grupo[0].nota.colunaH } });
    continue;
  }
  if (blocosOrdenados.length === 0) continue;

  // Gate de contrato POR GRUPO (secao 3.2.1, fechamento): se qualquer linha liberada, grupo inteiro libera.
  const algumaLiberada = blocosOrdenados.some((b) => b.liberado);
  if (!algumaLiberada) {
    saida.push({ json: { ...blocosOrdenados[0], acao: 'pendente_contrato' } });
    continue;
  }
  const linhasCorrigidas = blocosOrdenados.filter((b) => !b.liberado);

  const primeiro = blocosOrdenados[0];
  // Deduplicação do pedido (3.1.6) — SÓ em produção. Ver comentário equivalente no node
  // "Montar e-mail colaborador". No caso de fornecedor a chave é a da PRIMEIRA linha do
  // grupo, que é exatamente a que o fluxo grava em cobrancas.json para o grupo.
  const chaveDedup = primeiro.perfil.retranca + '_L' + primeiro.nota.linha;
  const entradaAnterior = (primeiro.cobrancas || {})[chaveDedup];
  if (primeiro.config && primeiro.config.ambiente === 'producao' && entradaAnterior && entradaAnterior.threadId) {
    saida.push({ json: { ...primeiro, acao: 'pedido_ja_criado', chaveCobranca: chaveDedup, threadIdExistente: entradaAnterior.threadId } });
    continue;
  }

  const temNotaFiscal = blocosOrdenados.some((b) => b.documentoLinha === 'NOTA_FISCAL');
  const dataVencimento = new Date(primeiro.nota.colunaG);
  const dataBase = primeiro.gatilho === 'PROGRAMAR_ATE' ? new Date(primeiro.dataProgramarAte) : hoje;
  const dataEnvio = primeiro.gatilho === 'PROGRAMAR_ATE' ? (function(){ const dd = new Date(dataBase); dd.setDate(dd.getDate()+5); return dd; })() : dataBase;
  const apelidoAtual = (primeiro.apelidos && primeiro.apelidos[primeiro.nota.projetoId] && primeiro.apelidos[primeiro.nota.projetoId].length) ? primeiro.apelidos[primeiro.nota.projetoId][primeiro.apelidos[primeiro.nota.projetoId].length - 1] : apelidoDoPerfil(primeiro.perfil);

  const corpo = montarCorpoEmailFornecedor({ blocosOrdenados, temNotaFiscal, dataEnvio, dataVencimento, textoRef: primeiro.perfil.texto_ref });
  let assunto = montarAssuntoFornecedor({ apelidoAtual, temNotaFiscal, parcela: primeiro.parcela, dataEnvio, fornecedor: primeiro.nota.colunaH });
  if (primeiro.escalaUrgencia === 0) assunto = 'URG | ' + assunto;

  // Ambiente troca APENAS destinatario e credencial (spec 7.4 e 3.5) — sem marca de
  // ambiente no assunto nem no corpo. Ver comentario no "Montar e-mail colaborador".
  const ehHomolog = primeiro.config && primeiro.config.ambiente === 'homolog';
  const emailDestino = ehHomolog ? EMAIL_TESTE_HOMOLOG : primeiro.nota.colunaR;
  const emailCopia = ehHomolog ? EMAIL_COPIA_HOMOLOG : EMAIL_COPIA_PRODUCAO;

  const decisao = decidirAcaoEnvio(primeiro.gatilho, ehModoAutomatico(primeiro.config), primeiro.forcarRascunho);

  saida.push({ json: {
    ...primeiro,
    acao: decisao.acaoGmail,
    atualizarColunaL: decisao.atualizarColunaL,
    novoValorColunaL: decisao.novoValorColunaL,
    emailDestino,
    emailCopia,
    assunto,
    corpoHtml: corpo,
    marcadores: ['IA', MARCADOR_PROJETO[primeiro.nota.projetoId]],
    chaveCobranca: primeiro.perfil.retranca + '_L' + primeiro.nota.linha,
    linhasAfetadas: blocosOrdenados.map((b) => ({ projetoId: b.nota.projetoId, linha: b.nota.linha, atualizarColunaNPara: b.liberado ? b.atualizarColunaNPara : 'OK - ASSINADO' })),
  } });

  if (linhasCorrigidas.length > 0) {
    saida.push({ json: {
      acao: 'avisar_correcao_contrato',
      fornecedor: primeiro.nota.colunaH,
      linhasCorrigidas: linhasCorrigidas.map((b) => ({ linha: b.nota.linha, valor: b.nota.colunaK })),
    } });
  }
}

return saida;

// Avalia cobranca para linhas ja SOLICITADA MI (fluxo='monitoramento') - secao 3.1.1.
// Schema de cobrancas.json ALINHADO ao spec.md: threadId, data_ultima_cobranca,
// contagem_cobrancas, status_ciclo ('em_andamento'|'encerrado_sem_resposta'|'recebido').
function somarDias(data, dias) { const d = new Date(data); d.setDate(d.getDate() + dias); return d; }
function diferencaDias(a, b) { const MS = 86400000; const u1 = Date.UTC(a.getFullYear(), a.getMonth(), a.getDate()); const u2 = Date.UTC(b.getFullYear(), b.getMonth(), b.getDate()); return Math.round((u1 - u2) / MS); }
function avaliarCobranca({ hoje, dataProgramarAte, dataVencimentoNF, estadoAtual }) {
  if (estadoAtual && estadoAtual.status_ciclo && estadoAtual.status_ciclo !== 'em_andamento') return { acao: 'nenhuma' };
  const fimDoCiclo = somarDias(dataVencimentoNF, -5);
  if (diferencaDias(hoje, dataProgramarAte) < 0) return { acao: 'nenhuma' };
  if (diferencaDias(hoje, fimDoCiclo) >= 0) {
    return { acao: 'encerrar_sem_resposta', novoEstado: { threadId: estadoAtual ? estadoAtual.threadId : null, data_ultima_cobranca: estadoAtual ? estadoAtual.data_ultima_cobranca : null, contagem_cobrancas: estadoAtual ? estadoAtual.contagem_cobrancas : 0, status_ciclo: 'encerrado_sem_resposta' } };
  }
  if (!estadoAtual) return { acao: 'nenhuma' }; // sem entrada em cobrancas.json ainda (threadId deveria ter sido gravado na criacao do pedido) - nada a fazer até existir.
  if (estadoAtual.contagem_cobrancas === 0) {
    const diaPrimeira = somarDias(dataProgramarAte, 1);
    if (diferencaDias(hoje, diaPrimeira) >= 0) {
      return { acao: 'cobrar', novoEstado: { threadId: estadoAtual.threadId, data_ultima_cobranca: hoje.toISOString().slice(0,10), contagem_cobrancas: 1, status_ciclo: 'em_andamento' } };
    }
    return { acao: 'nenhuma' };
  }
  const dataUltima = new Date(estadoAtual.data_ultima_cobranca);
  if (diferencaDias(hoje, dataUltima) >= 5) {
    return { acao: 'cobrar', novoEstado: { threadId: estadoAtual.threadId, data_ultima_cobranca: hoje.toISOString().slice(0,10), contagem_cobrancas: estadoAtual.contagem_cobrancas + 1, status_ciclo: 'em_andamento' } };
  }
  return { acao: 'nenhuma' };
}

const hoje = new Date();
return $input.all().map((item) => {
  const d = item.json;
  const vencimento = new Date(d.nota.colunaG);
  const chaveCobranca = d.perfil.retranca + '_L' + d.nota.linha;
  const estadoAtual = d.cobrancas ? d.cobrancas[chaveCobranca] : undefined;
  const dataProgramarAte = estadoAtual && estadoAtual.dataProgramarAteOriginal ? new Date(estadoAtual.dataProgramarAteOriginal) : hoje;
  const resultado = avaliarCobranca({ hoje, dataProgramarAte, dataVencimentoNF: vencimento, estadoAtual });
  const acao = resultado.acao === 'cobrar' ? (d.config.modo === 'automatico' ? 'cobrar_enviar' : 'cobrar_rascunho') : resultado.acao;
  return { json: { ...d, acao, chaveCobranca, novoEstadoCobranca: resultado.novoEstado, threadId: estadoAtual ? estadoAtual.threadId : null } };
});

// Consolida: (a) mudancas de coluna N/L a escrever no Box, (b) novo cobrancas.json,
// (c) resumo pro relatorio (incl. lacunas de informacao, correcoes de contrato e alertas
// de situacao nao mapeada), (d) registro no log diario pro /resumo (secao 7.3).
// Suporta itens de 1 linha (colaborador/cobranca/pendente) e itens de GRUPO fornecedor
// (varias linhas por item, campo linhasAfetadas — secao 3.2.1).

const itens = $input.all().map((i) => i.json);

const mudancasColunaN = [];
const mudancasColunaL = [];

for (const d of itens) {
  if (Array.isArray(d.linhasAfetadas)) {
    for (const la of d.linhasAfetadas) {
      if (la.atualizarColunaNPara) mudancasColunaN.push({ projetoId: la.projetoId, linha: la.linha, valor: la.atualizarColunaNPara });
      if (d.atualizarColunaL && d.novoValorColunaL) mudancasColunaL.push({ projetoId: la.projetoId, linha: la.linha, valor: d.novoValorColunaL });
    }
    continue;
  }
  if (d.atualizarColunaNPara) mudancasColunaN.push({ projetoId: d.nota.projetoId, linha: d.nota.linha, valor: d.atualizarColunaNPara });
  if (d.atualizarColunaL && d.novoValorColunaL) mudancasColunaL.push({ projetoId: d.nota.projetoId, linha: d.nota.linha, valor: d.novoValorColunaL });
}

const cobrancasAtualizadas = { ...(itens.find((d) => d.cobrancas) ? itens.find((d) => d.cobrancas).cobrancas : {}) };
for (const d of itens) {
  if (d.chaveCobranca && d.novoEstadoCobranca) cobrancasAtualizadas[d.chaveCobranca] = d.novoEstadoCobranca;
}

const alertasEncerramento = itens.filter((d) => d.acao === 'encerrar_sem_resposta');
const alertasSituacaoNaoMapeada = itens.filter((d) => d.acao === 'alerta_situacao_nao_mapeada');
const correcoesContrato = itens.filter((d) => d.acao === 'avisar_correcao_contrato');
const rascunhosCriados = itens.filter((d) => d.acao === 'criar_rascunho' || d.acao === 'cobrar_rascunho');
const enviosDiretos = itens.filter((d) => d.acao === 'enviar_direto' || d.acao === 'cobrar_enviar');
const pendentesContrato = itens.filter((d) => d.acao === 'pendente_contrato');
const comLacunaInformacao = itens.filter((d) => d.temLacunaInformacao);

const resumo = {
  rascunhosCriados: rascunhosCriados.length,
  enviosDiretos: enviosDiretos.length,
  pendentesContrato: pendentesContrato.length,
  comLacunaInformacao: comLacunaInformacao.length,
  alertasSituacaoNaoMapeada: alertasSituacaoNaoMapeada.length,
  correcoesContrato: correcoesContrato.length,
  alertasEncerramento: alertasEncerramento.map((a) => ({ colaboradorOuFornecedor: a.nomeColaborador || (a.nota && a.nota.colunaH), projetoId: a.nota && a.nota.projetoId })),
};

return [{ json: {
  mudancasColunaN, mudancasColunaL, cobrancasAtualizadas, resumo,
  logEntry: { timestamp: new Date().toISOString(), fase: 'fase1_solicitacao_nota', resumo },
} }];

// Aplica as mudanças de coluna N e L em memória (exceljs) e prepara o binário pra upload.
// Preserva ambiente + fileId no output pra o node seguinte decidir Drive vs Box.
// Leitura de binário: esta instância do n8n guarda binário no disco (filesystem-v2),
// então item.binary.data.data NÃO é o conteúdo, e sim o rótulo do modo de armazenamento.
// O único acesso liberado no Code Node é helpers.getBinaryDataBuffer, que lê pelo ÍNDICE
// do item no input DIRETO — daí localizarmos o item pelo id do binário. Cobre os 2 modos.
const helpers = this.helpers;
const entradasDoNode = $input.all();
async function bufferDe(item, prop) {
  prop = prop || 'data';
  const b = item && item.binary && item.binary[prop];
  if (!b) return null;
  if (!b.id) return Buffer.from(b.data, 'base64'); // modo embutido
  const i = entradasDoNode.findIndex((e) => e.binary && e.binary[prop] && e.binary[prop].id === b.id);
  if (i < 0) throw new Error('binario "' + (b.fileName || prop) + '" nao esta no input direto deste node — o Code Node so consegue le-lo por ai');
  return await helpers.getBinaryDataBuffer(i, prop);
}

const ExcelJS = require('exceljs');

// As mudanças vêm de "Preparar gravação da coluna N", que roda ANTES da escrita.
// Antes isto lia de "Consolidar mudanças e cobrancas.json" — e ficou obsoleto quando a
// gravação foi movida pra antes da criação do e-mail: aquele node passou a rodar no FIM do
// fluxo, depois do Gmail, e a leitura estourava com "hasn't been executed". O node existe e
// é alcançável; o problema era a ORDEM.
const consolidado = $('Preparar gravação da coluna N').first().json;
const mudancasN = consolidado.mudancasColunaN || [];
const mudancasL = consolidado.mudancasColunaL || [];
const contexto = $('Resolver arquivo-alvo da escrita').first().json;

// Nao citamos aqui o node de escolha do arquivo de homolog: ele so existe no arquivo de
// homologacao, e a citacao ficava pendurada no de producao — funcionava por acidente, presa
// a um try/catch. Quem precisa do id do arquivo do Drive e o proprio node de upload de
// homolog, que le direto da fonte e so existe naquele ambiente.

const item = $input.first();
const buffer = await bufferDe(item);
const wb = new ExcelJS.Workbook();
await wb.xlsx.load(buffer);
// A aba chama-se "NOTAS". getWorksheet() do exceljs e SENSIVEL A MAIUSCULAS, e o
// fallback silencioso "|| wb.worksheets[0]" mandava a escrita pra "DETALHADO MÃE" — foi
// o que aconteceu na execucao 86: os "OK - ASSINADO" foram parar na aba errada, nas
// mesmas linhas 293/404/631. Mesmo bug que ja tinha sido corrigido no node de LEITURA e
// que passou batido aqui. Sem fallback: se a aba nao existir, estoura.
const ws = wb.worksheets.find((w) => String(w.name).trim().toUpperCase() === 'NOTAS');
if (!ws) {
  throw new Error('aba "NOTAS" nao encontrada no arquivo-alvo. Abas: ' + wb.worksheets.map((w) => w.name).join(', '));
}

for (const m of mudancasN) {
  ws.getCell('N' + m.linha).value = m.valor;
}
for (const m of mudancasL) {
  ws.getCell('L' + m.linha).value = m.valor;
}

// Confere celula a celula que o valor entrou onde devia, na aba certa. Uma escrita em
// aba/linha errada volta a passar despercebida sem isto.
const divergentes = [];
for (const m of mudancasN) {
  const lido = ws.getCell('N' + m.linha).value;
  if (String(lido === null || lido === undefined ? '' : lido).trim() !== String(m.valor).trim()) {
    divergentes.push('N' + m.linha + ' esperava "' + m.valor + '" e ficou "' + lido + '"');
  }
}
for (const m of mudancasL) {
  const lido = ws.getCell('L' + m.linha).value;
  if (String(lido === null || lido === undefined ? '' : lido).trim() !== String(m.valor).trim()) {
    divergentes.push('L' + m.linha + ' esperava "' + m.valor + '" e ficou "' + lido + '"');
  }
}
if (divergentes.length) {
  throw new Error('gravacao na aba NOTAS nao conferiu: ' + divergentes.join('; '));
}

const novoBuffer = await wb.xlsx.writeBuffer();
return [{
  json: { ambiente: contexto.config.ambiente, fileIdBox: contexto.fileId, nomeArquivo: contexto.nomeArquivoHomolog },
  binary: { data: { data: Buffer.from(novoBuffer).toString('base64'), mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', fileName: 'cost_report_atualizado.xlsx' } },
}];

// Acrescenta o resumo desta execucao ao log diario (secao 7.3) — lido por
// workflows/resumo_diario.json. Mantem só os últimos 30 dias pra não crescer sem limite
// (não especificado no spec.md — escolha de implementação razoável, fácil de ajustar).
// Leitura de binário: esta instância do n8n guarda binário no disco (filesystem-v2),
// então item.binary.data.data NÃO é o conteúdo, e sim o rótulo do modo de armazenamento.
// O único acesso liberado no Code Node é helpers.getBinaryDataBuffer, que lê pelo ÍNDICE
// do item no input DIRETO — por isso "Ler log_diario.json" alimenta este node diretamente.
let log = [];
try {
  const b = $input.first().binary;
  if (b && b.data) {
    const buf = b.data.id ? await this.helpers.getBinaryDataBuffer(0, 'data') : Buffer.from(b.data.data, 'base64');
    log = JSON.parse(buf.toString('utf8'));
  }
} catch (e) { log = []; } // 1a execução: arquivo ainda não existe
log.push($('Consolidar mudanças e cobrancas.json').first().json.logEntry);
const LIMITE_DIAS = 30;
const corte = new Date(); corte.setDate(corte.getDate() - LIMITE_DIAS);
log = log.filter((e) => new Date(e.timestamp) >= corte);
return [{ json: {}, binary: { data: { data: Buffer.from(JSON.stringify(log, null, 2)).toString('base64'), mimeType: 'application/json', fileName: 'log_diario.json' } } }];

// Monta a 1a entrada de cobrancas.json (secao 3.1.1: "o threadId e gravado assim que o
// e-mail de pedido e criado"). O payload e o threadId ja vem casados do node anterior,
// entao aqui o indice e dentro da propria ramificacao — 1:1, sem risco de trocar item.
const pedidos = $('Casar resposta do Gmail (rascunho pedido)').all();

return $input.all().map((item, i) => {
  const d = (pedidos[i] || {}).json || {};
  const hoje = new Date();
  return { json: {
    ...d,
    novoEstadoCobranca: {
      threadId: d.threadIdGmail || null,
      data_ultima_cobranca: hoje.toISOString().slice(0, 10),
      contagem_cobrancas: 0,
      status_ciclo: 'em_andamento',
    },
  } };
});

// Monta a 1a entrada de cobrancas.json (secao 3.1.1: "o threadId e gravado assim que o
// e-mail de pedido e criado"). O payload e o threadId ja vem casados do node anterior,
// entao aqui o indice e dentro da propria ramificacao — 1:1, sem risco de trocar item.
const pedidos = $('Casar resposta do Gmail (envio pedido)').all();

return $input.all().map((item, i) => {
  const d = (pedidos[i] || {}).json || {};
  const hoje = new Date();
  return { json: {
    ...d,
    novoEstadoCobranca: {
      threadId: d.threadIdGmail || null,
      data_ultima_cobranca: hoje.toISOString().slice(0, 10),
      contagem_cobrancas: 0,
      status_ciclo: 'em_andamento',
    },
  } };
});

// Resolve QUAL arquivo receberá a escrita, e reanexa o contexto que se perde antes daqui.
//
// O "Consolidar mudanças e cobrancas.json" monta um item NOVO (mudancas + resumo + log) e
// deixa o config pra tras. Sem ele:
//   - homolog: a busca do arquivo-alvo montava "'' in parents" e o Drive respondia
//     404 "File not found: ." (foi o erro da execucao 82);
//   - producao: "Box — Lock" receberia fileId undefined;
//   - os dois: "Aplicar mudancas" quebraria em contexto.config.ambiente.
// Esse ramo so executa quando ha mudanca de coluna N/L pra gravar, e ate a execucao 82
// nunca tinha havido nenhuma — por isso o problema so apareceu agora.
//
// LIMITACAO CONHECIDA (pre-existente): resolve so 1 arquivo-alvo por execucao, a partir do
// projetoId da 1a mudanca. Se houver mudancas em S01 E S02 na mesma execucao, so o do
// primeiro projetoId e escrito nesta versao.

// ATENCAO: estes ids repetem os que estao fixos nos nodes "Box — Download Cost Report".
// Se o arquivo do Box mudar, os dois lugares precisam ser atualizados juntos.
const BOX_FILE_ID = {
  AREP: '2028817453680',      // S01 — mesmo arquivo do Reunion (spec secao 6)
  REUNION: '2028817453680',
  SOFT_PRE: '2366859928452',  // S02
};
const NOME_HOMOLOG = {
  SOFT_PRE: 'BR_SMTC_S02_SOFTPRE_PROVISÓRIO.xlsx',
};
const NOME_HOMOLOG_PADRAO = 'BR_SMTC_S01__COST REPORT_VS_EXECUÇÃO_1201.xlsx';

const d = $input.first().json;
const config = $('Carregar config + perfis').first().json.config;

const primeira = (d.mudancasColunaN && d.mudancasColunaN[0]) || (d.mudancasColunaL && d.mudancasColunaL[0]);
const projetoId = primeira ? primeira.projetoId : 'REUNION';

return [{ json: {
  ...d,
  config,
  projetoId,
  nomeArquivoHomolog: NOME_HOMOLOG[projetoId] || NOME_HOMOLOG_PADRAO,
  fileId: BOX_FILE_ID[projetoId] || BOX_FILE_ID.AREP,
} }];

