={{ JSON.stringify({
  model: 'claude-haiku-4-5',
  max_tokens: 1024,
  system: "Voce extrai dados estruturados da coluna "Descricao" (coluna J) de uma planilha de controle de notas fiscais da produtora Box Fish.

O texto pode descrever:
(a) um COLABORADOR prestando servico - geralmente tem um Cargo, um Nome de pessoa, e opcionalmente um periodo (DD/MM A DD/MM) e uma palavra-chave de tipo entre parenteses (JOB, DIARIA, DIARIAS, PACOTE, REC, REC+NF); ou
(b) um FORNECEDOR de locacao/recibo - geralmente e uma empresa (razao social), sem nome de pessoa fisica, descrevendo uma locacao (equipamento, estudio, gerador etc.) ou um servico faturado por fornecedor.

Responda SOMENTE com um objeto JSON (sem markdown, sem texto fora do JSON) no formato:
{"tipoLinha": "colaborador"|"fornecedor", "periodo": "DD/MM A DD/MM"|null, "tipoEmissao": "NF_NORMAL"|"JOB"|"DIARIA"|"PACOTE"|"REC"|"REC_NF"|null, "parcela": "P.X/Y"|null, "cargo": string|"FALTA INFORMACAO"|null, "nomeColaborador": string|"FALTA INFORMACAO"|null, "documentoLinha": "RECIBO"|"NOTA_FISCAL"|null, "descricaoServicoOuLocacao": string, "situacaoNaoMapeada": string|null}

Regras: no campo cargo, REMOVA qualquer numeracao no final (ex.: "ASS. DE CONTROLLER 1" -> "ASS. DE CONTROLLER"; "CONTRARREGRA 2" -> "CONTRARREGRA"); Regras: tipoEmissao so se aplica a colaborador (JOB/DIARIA/PACOTE) ou fornecedor (REC/REC_NF); ausencia de palavra-chave em colaborador = NF_NORMAL. documentoLinha so se aplica a fornecedor: use o prefixo (REC)/(NF) quando existir; se nao houver marcacao inequivoca, infira semanticamente SO se estiver claro, senao null. descricaoServicoOuLocacao: sem nome do projeto (REUNION, AREP, SOFT PRE, PNS, PNL etc.) e sem o periodo. Se nao conseguir preencher cargo/nomeColaborador com confianca, use FALTA INFORMACAO - nunca invente. Se achar qualquer situacao nao coberta por estas regras, preencha situacaoNaoMapeada descrevendo o problema - nunca adivinhe um valor pra contornar isso.",
  messages: [{ role: 'user', content: JSON.stringify({ colunaJ: $json.nota.colunaJ || '', colunaH: $json.nota.colunaH || '' }) }]
}) }}

parameters.jsCode:
// Monta o mapa nome -> id dos marcadores do Gmail.
// Usado pelos nodes 'Gmail — Aplicar marcadores (...)', porque a API
// aceita só ID de marcador, e o spec.md (3.1.2) define os marcadores por NOME.
const mapa = {};
for (const item of $input.all()) {
  const l = item.json;
  if (l && l.name && l.id) mapa[l.name] = l.id;
}
const esperados = ['IA', 'REUNION - PEDIDO DE NOTAS', 'SOFT PRE - PEDIDO NOTAS', 'AREP - PEDIDO DE NOTAS', 'CONTRATAÇÃO'];
const faltando = esperados.filter((n) => !mapa[n]);
// Não interrompe a execução: marcador faltando é problema de cadastro no Gmail,
// não motivo pra travar o pedido de nota. Fica registrado pro relatório.
return [{ json: { mapa, marcadoresFaltando: faltando } }];

// A resposta do addLabels nao carrega os campos que o consolidador usa (acao,
// chaveCobranca, novoEstadoCobranca...). Restaura o payload ja casado no node anterior —
// indice dentro da propria ramificacao, 1:1.
const pedidos = $('Casar resposta do Gmail (cobrança rascunho)').all();
return $input.all().map((item, i) => ({ json: (pedidos[i] || {}).json || {} }));

// A resposta do addLabels nao carrega os campos que o consolidador usa (acao,
// chaveCobranca, novoEstadoCobranca...). Restaura o payload ja casado no node anterior —
// indice dentro da propria ramificacao, 1:1.
const pedidos = $('Casar resposta do Gmail (cobrança envio)').all();
return $input.all().map((item, i) => ({ json: (pedidos[i] || {}).json || {} }));

// Ponto de partida das duas checagens paralelas (spec 3.1). Existe por dois motivos:
// dar um ponto de ramificação explícito, e servir de referência estável — o node da ficha
// cadastral precisa mapear cada mensagem do Gmail de volta pra linha que a originou.
return $input.all();

// Checagem A das duas paralelas (spec 3.1): cruzamento com a planilha de Contratos.
// Critério LITERAL "ASSINADO" — qualquer outro valor ("E A dd/mm", vazio, "AGUARDANDO
// ASSINATURA DO CONTRATO"...) não confirma e não escreve nada na coluna N.

function normalizar(texto) {
  if (!texto) return '';
  return String(texto).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}

function contratoAssinadoNaPlanilha(status) {
  return normalizar(status) === 'assinado';
}

function cruzarComPlanilhaContratos(nota, linhasContratos) {
  const alvoRazao = normalizar(nota.colunaH);
  const partes = (nota.colunaJ || '').split(' - ');
  const alvoNome = normalizar(partes.length >= 2 ? partes[1] : nota.colunaH);
  const encontrada = (linhasContratos || []).find((linha) => {
    const razao = normalizar(linha.razaoSocial);
    const nome = normalizar(linha.nomeColaborador);
    return (alvoRazao && razao === alvoRazao) || (alvoNome && nome === alvoNome);
  });
  return !!encontrada && contratoAssinadoNaPlanilha(encontrada.status);
}

// Lido uma vez, da fonte — e não de dentro de cada item, que era o que inflava o
// payload em duas ordens de grandeza (ver comentário no node de parse).
const contratosPorProjeto = $('Parsear planilhas (exceljs) e separar AREP/Reunion por cor')
  .first().json.contratosPorProjeto || {};

return $input.all().map((item) => {
  const confirmado = cruzarComPlanilhaContratos(item.json.nota, contratosPorProjeto[item.json.nota.projetoId]);
  return { json: {
    ...item.json,
    fonteChecagem: 'planilha_contratos',
    confirmado,
    // spec 3.1: match na planilha preenche a coluna N como "OK - ASSINADO"
    atualizarColunaNPara: confirmado ? 'OK - ASSINADO' : undefined,
  } };
});

// Junta as duas checagens paralelas (spec 3.1): a PRIMEIRA confirmação positiva libera,
// sem prioridade entre as fontes. Como as duas chegam pelo mesmo Merge, "primeira" aqui é
// "qualquer uma que tenha confirmado" — o resultado é o mesmo, e não depende de qual
// terminou antes.
//
// Cada linha pode aparecer até 2x no input (uma por checagem); o agrupamento é por
// chaveLinha. Linhas já resolvidas pela coluna N vêm por outro ramo e passam direto.

const porLinha = new Map();

for (const item of $input.all()) {
  const d = item.json;
  const chave = d.chaveLinha;
  if (chave === null || chave === undefined) continue;

  if (!porLinha.has(chave)) {
    porLinha.set(chave, { base: d, liberado: false, motivo: undefined, valorColunaN: undefined, passaDireto: false });
  }
  const acc = porLinha.get(chave);

  // monitoramento e linhas liberadas pela coluna N não passam pelas checagens paralelas
  if (d.contratoResolvido) {
    acc.base = d;
    acc.passaDireto = true;
    continue;
  }
  acc.base = { ...acc.base, ...d };
  if (d.confirmado && !acc.liberado) {
    acc.liberado = true;
    acc.motivo = d.fonteChecagem;
    acc.valorColunaN = d.atualizarColunaNPara;
  }
}

return [...porLinha.values()].map(({ base, liberado, motivo, valorColunaN, passaDireto }) => {
  if (passaDireto) return { json: base };
  const json = { ...base, liberado, motivoLiberacao: motivo, atualizarColunaNPara: valorColunaN };
  delete json.confirmado;
  delete json.fonteChecagem;
  return { json };
});

// Serializa o cobrancas.json atualizado em binário: o node de escrita em disco só aceita
// binário, não JSON. Mesmo padrão do "Preparar log_diario.json atualizado".
//
// Node separado de propósito, em vez de emitir o binário lá no "Consolidar": aquele node
// alimenta 4 ramos, e pendurar o arquivo serializado no item faria os 4 carregarem uma
// cópia — a mesma duplicação de payload que travou a VM.
const cobrancas = $input.first().json.cobrancasAtualizadas || {};
return [{
  json: {},
  binary: { data: {
    data: Buffer.from(JSON.stringify(cobrancas, null, 2)).toString('base64'),
    mimeType: 'application/json',
    fileName: 'cobrancas.json',
  } },
}];

// Âncora de correlação pra chamada da IA. O node HTTP substitui o json do item pela
// resposta da API, então o contexto da linha (nota, perfil, config, apelidos, liberado...)
// precisa ser recuperado depois — e pra isso é preciso um node estável pra casar via
// pairedItem. Não transforma nada, só passa adiante.
return $input.all();

// Junta as mudancas de planilha dos itens JA montados (o e-mail so foi montado em
// memoria ate aqui — nada foi criado no Gmail ainda). Roda antes do "Switch — ação"
// justamente pra que a gravacao aconteca ANTES da criacao do e-mail: se a escrita
// falhar, a execucao para aqui e nenhum rascunho e criado.
//
// A regra (secao 3.1): e-mail so pode existir com contrato confirmado E coluna N
// efetivamente gravada. Antes, a gravacao rodava no fim do fluxo — os e-mails ja
// existiam quando ela falhava.
const itens = $input.all().map((i) => i.json);

const mudancasColunaN = [];
const mudancasColunaL = [];
for (const d of itens) {
  if (Array.isArray(d.linhasAfetadas)) {
    for (const la of d.linhasAfetadas) {
      if (la.atualizarColunaNPara) mudancasColunaN.push({ projetoId: la.projetoId, linha: la.linha, valor: la.atualizarColunaNPara });
      if (d.atualizarColunaL && d.novoValorColunaL) mudancasColunaL.push({ projetoId: la.projetoId, linha: la.linha, valor: d.novoValorColunaL });
    }
    continue;
  }
  if (!d.nota) continue;
  if (d.atualizarColunaNPara) mudancasColunaN.push({ projetoId: d.nota.projetoId, linha: d.nota.linha, valor: d.atualizarColunaNPara });
  if (d.atualizarColunaL && d.novoValorColunaL) mudancasColunaL.push({ projetoId: d.nota.projetoId, linha: d.nota.linha, valor: d.novoValorColunaL });
}

// A coluna L NÃO vai junto: ela só pode ser escrita depois do envio confirmado
// (spec 3.1.5). Quem cuida dela é a cadeia "...(coluna L)", lá no fim do fluxo.
return [{ json: { mudancasColunaN, mudancasColunaL: [] } }];

// So chega aqui se a gravacao da planilha subiu (ou se nao havia nada a gravar).
// Reemite os itens montados, que seguem pro Switch e dai pro Gmail.
return $('Merge — rotas (cobrança/colaborador/fornecedor)').all();

// Confirmação pós-escrita (spec 3.1.5). Relê o arquivo COMO ELE FICOU SALVO — não o
// workbook em memória — e confere cada célula que a automação diz ter escrito.
//
// A verificação em memória (no node "Aplicar mudanças") continua valendo: ela pega aba ou
// linha erradas antes de subir. Esta aqui pega o que aquela não alcança: upload que
// responde OK sem persistir, upload no arquivo errado, ou versão sobrescrita no meio.
const ExcelJS = require('exceljs');

const contexto = $('Aplicar mudanças (exceljs) e preparar upload').first().json;
const mudancas = $('Preparar gravação da coluna N').first().json;
const esperados = []
  .concat((mudancas.mudancasColunaN || []).map((m) => ({ celula: 'N' + m.linha, valor: m.valor })))
  .concat((mudancas.mudancasColunaL || []).map((m) => ({ celula: 'L' + m.linha, valor: m.valor })));

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const wb = new ExcelJS.Workbook();
await wb.xlsx.load(buffer);
const ws = wb.worksheets.find((w) => String(w.name).trim().toUpperCase() === 'NOTAS');

const divergencias = [];
if (!ws) {
  divergencias.push('aba "NOTAS" nao existe no arquivo relido (abas: ' + wb.worksheets.map((w) => w.name).join(', ') + ')');
} else {
  for (const e of esperados) {
    const bruto = ws.getCell(e.celula).value;
    const lido = bruto === null || bruto === undefined ? '' : String(bruto).trim();
    if (lido !== String(e.valor).trim()) {
      divergencias.push(e.celula + ': tentou gravar "' + e.valor + '", releitura encontrou "' + (lido || '(vazio)') + '"');
    }
  }
}

const confirmado = divergencias.length === 0;

// O texto do alerta é montado depois, por ambiente: em produção ele precisa dizer se a
// reversão para a versão anterior deu certo; em homolog, que NÃO há reversão automática.
return [{ json: {
  confirmado,
  divergencias,
  celulasConferidas: esperados.length,
  arquivoId: contexto.nomeArquivo || contexto.fileIdBox || '(desconhecido)',
} }];

const d = $('Confirmar escrita na planilha').first().json;
const linhas = (d.divergencias || []).map((x) => '• ' + x);

// A revisão anterior foi restaurada logo antes deste alerta (baixar a revisão + subir de
// volta — o Drive não tem "promover revisão" como o Box). O node de restauração usa
// neverError, então o resultado real vem no corpo e é reportado aqui: se a reversão
// falhar, o alerta diz isso, em vez de dar a impressão de que o arquivo está limpo.
const resp = $input.first().json || {};
const status = resp.statusCode;
const corpo = resp.body || resp;
const reverteu = status >= 200 && status < 300;

let idRevisao = '(desconhecida)';
try {
  const revs = $('Drive (homolog) — Guardar revisão anterior').first().json.revisions || [];
  if (revs.length) idRevisao = revs[revs.length - 1].id;
} catch (e) { /* sem lista de revisões */ }

const texto = [
  '🚨 Escrita na planilha NAO confirmada — processamento abortado',
  '',
  'Nenhum e-mail foi criado nesta execução.',
  'Ambiente: homologação (Drive)',
  'Arquivo: ' + d.arquivoId,
  'Aba: NOTAS',
  '',
  reverteu
    ? '✅ Arquivo REVERTIDO para a revisão anterior (' + idRevisao + ').'
    : '⚠️ FALHOU a reversão automática (HTTP ' + status + ' ' + (((corpo || {}).error || {}).message || (corpo || {}).message || '') + '). O arquivo pode ter ficado com a escrita não confirmada — conferir manualmente.',
  '',
  'Divergências (' + linhas.length + '):',
].concat(linhas).join('\n');

return [{ json: { textoAlerta: texto } }];

// A resposta do Gmail substitui o json do item pelos ids do rascunho/mensagem, levando
// embora o payload do pedido (marcadores, acao, chaveCobranca...). Aqui os dois sao casados.
//
// O pareamento e por indice contra a SAIDA 0 do Switch — e nao contra
// $('Merge — rotas...').all()[i]. O Switch DIVIDE os itens entre as saidas, entao o indice
// desta ramificacao nao corresponde ao indice no Merge: com um mix de acoes na mesma
// execucao, a correlacao antiga devolvia o payload de OUTRA linha.
const pedidos = $('Switch — ação').all(0).map((i) => i.json);

return $input.all().map((item, i) => {
  const j = item.json || {};
  const msg = j.message || {};
  return { json: {
    ...(pedidos[i] || {}),
    draftId: j.id || null,
    messageId: msg.id || j.id || null,
    threadIdGmail: msg.threadId || j.threadId || null,
  } };
});

// A resposta do Gmail substitui o json do item pelos ids do rascunho/mensagem, levando
// embora o payload do pedido (marcadores, acao, chaveCobranca...). Aqui os dois sao casados.
//
// O pareamento e por indice contra a SAIDA 1 do Switch — e nao contra
// $('Merge — rotas...').all()[i]. O Switch DIVIDE os itens entre as saidas, entao o indice
// desta ramificacao nao corresponde ao indice no Merge: com um mix de acoes na mesma
// execucao, a correlacao antiga devolvia o payload de OUTRA linha.
const pedidos = $('Switch — ação').all(1).map((i) => i.json);

return $input.all().map((item, i) => {
  const j = item.json || {};
  const msg = j.message || {};
  return { json: {
    ...(pedidos[i] || {}),
    draftId: j.id || null,
    messageId: msg.id || j.id || null,
    threadIdGmail: msg.threadId || j.threadId || null,
  } };
});

// A resposta do Gmail substitui o json do item pelos ids do rascunho/mensagem, levando
// embora o payload do pedido (marcadores, acao, chaveCobranca...). Aqui os dois sao casados.
//
// O pareamento e por indice contra a SAIDA 3 do Switch — e nao contra
// $('Merge — rotas...').all()[i]. O Switch DIVIDE os itens entre as saidas, entao o indice
// desta ramificacao nao corresponde ao indice no Merge: com um mix de acoes na mesma
// execucao, a correlacao antiga devolvia o payload de OUTRA linha.
const pedidos = $('Switch — ação').all(3).map((i) => i.json);

return $input.all().map((item, i) => {
  const j = item.json || {};
  const msg = j.message || {};
  return { json: {
    ...(pedidos[i] || {}),
    draftId: j.id || null,
    messageId: msg.id || j.id || null,
    threadIdGmail: msg.threadId || j.threadId || null,
  } };
});

// A resposta do Gmail substitui o json do item pelos ids do rascunho/mensagem, levando
// embora o payload do pedido (marcadores, acao, chaveCobranca...). Aqui os dois sao casados.
//
// O pareamento e por indice contra a SAIDA 4 do Switch — e nao contra
// $('Merge — rotas...').all()[i]. O Switch DIVIDE os itens entre as saidas, entao o indice
// desta ramificacao nao corresponde ao indice no Merge: com um mix de acoes na mesma
// execucao, a correlacao antiga devolvia o payload de OUTRA linha.
const pedidos = $('Switch — ação').all(4).map((i) => i.json);

return $input.all().map((item, i) => {
  const j = item.json || {};
  const msg = j.message || {};
  return { json: {
    ...(pedidos[i] || {}),
    draftId: j.id || null,
    messageId: msg.id || j.id || null,
    threadIdGmail: msg.threadId || j.threadId || null,
  } };
});

// Resolve QUAL arquivo receberá a escrita, e reanexa o contexto que se perde antes daqui.
//
// O "Consolidar mudanças e cobrancas.json" monta um item NOVO (mudancas + resumo + log) e
// deixa o config pra tras. Sem ele:
//   - homolog: a busca do arquivo-alvo montava "'' in parents" e o Drive respondia
//     404 "File not found: ." (foi o erro da execucao 82);
//   - producao: "Box — Lock" receberia fileId undefined;
//   - os dois: "Aplicar mudancas" quebraria em contexto.config.ambiente.
// Esse ramo so executa quando ha mudanca de coluna N/L pra gravar, e ate a execucao 82
// nunca tinha havido nenhuma — por isso o problema so apareceu agora.
//
// LIMITACAO CONHECIDA (pre-existente): resolve so 1 arquivo-alvo por execucao, a partir do
// projetoId da 1a mudanca. Se houver mudancas em S01 E S02 na mesma execucao, so o do
// primeiro projetoId e escrito nesta versao.

// ATENCAO: estes ids repetem os que estao fixos nos nodes "Box — Download Cost Report".
// Se o arquivo do Box mudar, os dois lugares precisam ser atualizados juntos.
const BOX_FILE_ID = {
  AREP: '2028817453680',      // S01 — mesmo arquivo do Reunion (spec secao 6)
  REUNION: '2028817453680',
  SOFT_PRE: '2366859928452',  // S02
};
const NOME_HOMOLOG = {
  SOFT_PRE: 'BR_SMTC_S02_SOFTPRE_PROVISÓRIO.xlsx',
};
const NOME_HOMOLOG_PADRAO = 'BR_SMTC_S01__COST REPORT_VS_EXECUÇÃO_1201.xlsx';

const d = $input.first().json;
const config = $('Carregar config + perfis').first().json.config;

const primeira = (d.mudancasColunaN && d.mudancasColunaN[0]) || (d.mudancasColunaL && d.mudancasColunaL[0]);
const projetoId = primeira ? primeira.projetoId : 'REUNION';

return [{ json: {
  ...d,
  config,
  projetoId,
  nomeArquivoHomolog: NOME_HOMOLOG[projetoId] || NOME_HOMOLOG_PADRAO,
  fileId: BOX_FILE_ID[projetoId] || BOX_FILE_ID.AREP,
} }];

// Aplica as mudanças de coluna N e L em memória (exceljs) e prepara o binário pra upload.
// Preserva ambiente + fileId no output pra o node seguinte decidir Drive vs Box.
// Leitura de binário: esta instância do n8n guarda binário no disco (filesystem-v2),
// então item.binary.data.data NÃO é o conteúdo, e sim o rótulo do modo de armazenamento.
// O único acesso liberado no Code Node é helpers.getBinaryDataBuffer, que lê pelo ÍNDICE
// do item no input DIRETO — daí localizarmos o item pelo id do binário. Cobre os 2 modos.
const helpers = this.helpers;
const entradasDoNode = $input.all();
async function bufferDe(item, prop) {
  prop = prop || 'data';
  const b = item && item.binary && item.binary[prop];
  if (!b) return null;
  if (!b.id) return Buffer.from(b.data, 'base64'); // modo embutido
  const i = entradasDoNode.findIndex((e) => e.binary && e.binary[prop] && e.binary[prop].id === b.id);
  if (i < 0) throw new Error('binario "' + (b.fileName || prop) + '" nao esta no input direto deste node — o Code Node so consegue le-lo por ai');
  return await helpers.getBinaryDataBuffer(i, prop);
}

const ExcelJS = require('exceljs');

// As mudanças vêm de "Preparar gravação da coluna L", que roda ANTES da escrita.
// Antes isto lia de "Consolidar mudanças e cobrancas.json" — e ficou obsoleto quando a
// gravação foi movida pra antes da criação do e-mail: aquele node passou a rodar no FIM do
// fluxo, depois do Gmail, e a leitura estourava com "hasn't been executed". O node existe e
// é alcançável; o problema era a ORDEM.
const consolidado = $('Preparar gravação da coluna L').first().json;
const mudancasN = consolidado.mudancasColunaN || [];
const mudancasL = consolidado.mudancasColunaL || [];
const contexto = $('Resolver arquivo-alvo da escrita (coluna L)').first().json;

// Nao citamos aqui o node de escolha do arquivo de homolog: ele so existe no arquivo de
// homologacao, e a citacao ficava pendurada no de producao — funcionava por acidente, presa
// a um try/catch. Quem precisa do id do arquivo do Drive e o proprio node de upload de
// homolog, que le direto da fonte e so existe naquele ambiente.

const item = $input.first();
const buffer = await bufferDe(item);
const wb = new ExcelJS.Workbook();
await wb.xlsx.load(buffer);
// A aba chama-se "NOTAS". getWorksheet() do exceljs e SENSIVEL A MAIUSCULAS, e o
// fallback silencioso "|| wb.worksheets[0]" mandava a escrita pra "DETALHADO MÃE" — foi
// o que aconteceu na execucao 86: os "OK - ASSINADO" foram parar na aba errada, nas
// mesmas linhas 293/404/631. Mesmo bug que ja tinha sido corrigido no node de LEITURA e
// que passou batido aqui. Sem fallback: se a aba nao existir, estoura.
const ws = wb.worksheets.find((w) => String(w.name).trim().toUpperCase() === 'NOTAS');
if (!ws) {
  throw new Error('aba "NOTAS" nao encontrada no arquivo-alvo. Abas: ' + wb.worksheets.map((w) => w.name).join(', '));
}

for (const m of mudancasN) {
  ws.getCell('N' + m.linha).value = m.valor;
}
for (const m of mudancasL) {
  ws.getCell('L' + m.linha).value = m.valor;
}

// Confere celula a celula que o valor entrou onde devia, na aba certa. Uma escrita em
// aba/linha errada volta a passar despercebida sem isto.
const divergentes = [];
for (const m of mudancasN) {
  const lido = ws.getCell('N' + m.linha).value;
  if (String(lido === null || lido === undefined ? '' : lido).trim() !== String(m.valor).trim()) {
    divergentes.push('N' + m.linha + ' esperava "' + m.valor + '" e ficou "' + lido + '"');
  }
}
for (const m of mudancasL) {
  const lido = ws.getCell('L' + m.linha).value;
  if (String(lido === null || lido === undefined ? '' : lido).trim() !== String(m.valor).trim()) {
    divergentes.push('L' + m.linha + ' esperava "' + m.valor + '" e ficou "' + lido + '"');
  }
}
if (divergentes.length) {
  throw new Error('gravacao na aba NOTAS nao conferiu: ' + divergentes.join('; '));
}

const novoBuffer = await wb.xlsx.writeBuffer();
return [{
  json: { ambiente: contexto.config.ambiente, fileIdBox: contexto.fileId, nomeArquivo: contexto.nomeArquivoHomolog },
  binary: { data: { data: Buffer.from(novoBuffer).toString('base64'), mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', fileName: 'cost_report_atualizado.xlsx' } },
}];

// Confirmação pós-escrita (spec 3.1.5). Relê o arquivo COMO ELE FICOU SALVO — não o
// workbook em memória — e confere cada célula que a automação diz ter escrito.
//
// A verificação em memória (no node "Aplicar mudanças") continua valendo: ela pega aba ou
// linha erradas antes de subir. Esta aqui pega o que aquela não alcança: upload que
// responde OK sem persistir, upload no arquivo errado, ou versão sobrescrita no meio.
const ExcelJS = require('exceljs');

const contexto = $('Aplicar mudanças (exceljs) e preparar upload (coluna L)').first().json;
const mudancas = $('Preparar gravação da coluna L').first().json;
const esperados = []
  .concat((mudancas.mudancasColunaN || []).map((m) => ({ celula: 'N' + m.linha, valor: m.valor })))
  .concat((mudancas.mudancasColunaL || []).map((m) => ({ celula: 'L' + m.linha, valor: m.valor })));

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const wb = new ExcelJS.Workbook();
await wb.xlsx.load(buffer);
const ws = wb.worksheets.find((w) => String(w.name).trim().toUpperCase() === 'NOTAS');

const divergencias = [];
if (!ws) {
  divergencias.push('aba "NOTAS" nao existe no arquivo relido (abas: ' + wb.worksheets.map((w) => w.name).join(', ') + ')');
} else {
  for (const e of esperados) {
    const bruto = ws.getCell(e.celula).value;
    const lido = bruto === null || bruto === undefined ? '' : String(bruto).trim();
    if (lido !== String(e.valor).trim()) {
      divergencias.push(e.celula + ': tentou gravar "' + e.valor + '", releitura encontrou "' + (lido || '(vazio)') + '"');
    }
  }
}

const confirmado = divergencias.length === 0;

// O texto do alerta é montado depois, por ambiente: em produção ele precisa dizer se a
// reversão para a versão anterior deu certo; em homolog, que NÃO há reversão automática.
return [{ json: {
  confirmado,
  divergencias,
  celulasConferidas: esperados.length,
  arquivoId: contexto.nomeArquivo || contexto.fileIdBox || '(desconhecido)',
} }];

// Segunda escrita da planilha: SÓ a coluna L (Status Box), e SÓ aqui — depois do envio.
//
// Este node fica pendurado em "Consolidar mudanças e cobrancas.json", que só roda depois
// dos nodes de envio do Gmail. Chegar aqui já significa que o e-mail saiu: se o envio
// falhasse, a execução teria parado antes e a coluna L não seria tocada (spec 3.1.5).
//
// Em MODO_EXECUCAO=rascunho a lista vem vazia (atualizarColunaL é false), então o IF
// seguinte corta o caminho e nada é gravado.
const d = $input.first().json;
return [{ json: { mudancasColunaN: [], mudancasColunaL: d.mudancasColunaL || [] } }];

const d = $('Confirmar escrita na planilha (coluna L)').first().json;
const linhas = (d.divergencias || []).map((x) => '• ' + x);

// Alerta da SEGUNDA escrita (coluna L), que acontece depois do e-mail já ter saído.
// Por isso o texto é diferente do alerta da coluna N: aqui não há e-mail a evitar — o
// que importa é avisar que o Status Box pode não refletir o envio que já aconteceu.
const texto = [
  '🚨 Escrita da coluna L (Status Box) NAO confirmada',
  '',
  'O e-mail JÁ FOI ENVIADO — o que falhou foi a atualização do Status Box.',
  'Arquivo: ' + d.arquivoId,
  'Aba: NOTAS',
  '',
  '⚠️ Conferir e corrigir o Status Box à mão nas linhas abaixo.',
  '',
  'Divergências (' + linhas.length + '):',
].concat(linhas).join('\n');

return [{ json: { textoAlerta: texto } }];
